using System;
using UnityEngine;
using LWS.TruckHockey;
namespace LWS.TruckAirHockey.Editor {
public static class AirHockeyFixtures {
 public static void Run(){int count=0;Action<bool,string> check=(value,name)=>{if(!value)throw new Exception("Air Hockey fixture: "+name);count++;};var r=new AirHockeyRules();r.Start(0);check(r.Server==0&&r.Score[0]==0&&r.Phase==AirHockeyPhase.Countdown,"fair initial serve");check(!r.Step(Vector3.zero,new Vector3(14,0,0),12,2.1f,.43f),"countdown blocks scoring");r.Tick(2);check(r.Live,"countdown advances");check(!r.Step(new Vector3(11,0,0),new Vector3(12.42f,0,0),12,2.1f,.43f),"partial puck rejected");check(!r.Step(new Vector3(11,0,2),new Vector3(14,0,2),12,2.1f,.43f),"outside opening rejected");check(r.Step(new Vector3(11,0,0),new Vector3(14,0,0),12,2.1f,.43f)&&r.Score[0]==1,"right goal credits left participant");check(r.Server==1,"conceding side serves");check(!r.Step(new Vector3(11,0,0),new Vector3(14,0,0),12,2.1f,.43f)&&r.Goals==1,"goal locked once");r.Pause();float timer=r.Timer;r.Tick(100);check(r.Phase==AirHockeyPhase.Paused&&r.Timer==timer,"pause preserves phase timer");r.Resume();check(r.Phase==AirHockeyPhase.Goal,"resume returns goal phase");r.Tick(2);check(r.Server==1&&r.Phase==AirHockeyPhase.Countdown,"conceding serve countdown");r.Tick(2);check(r.Step(new Vector3(-11,0,0),new Vector3(-14,0,0),12,2.1f,.43f)&&r.Score[1]==1,"left goal credits right including own goal");r.Tick(2);r.Tick(2);r.Serve(1);check(r.Score[0]==1&&r.Score[1]==1,"recovery preserves score");r.Tick(2);for(int i=0;i<6;i++){check(r.Step(new Vector3(11,0,0),new Vector3(14,0,0),12,2.1f,.43f),"point "+i);if(i<5){r.Tick(2);r.Tick(2);}}check(r.Winner==0&&r.Score[0]==7&&r.Phase==AirHockeyPhase.Finished,"exact first to seven stops");check(!r.Step(new Vector3(11,0,0),new Vector3(14,0,0),12,2.1f,.43f),"no scoring after result");r.Start(1);check(r.Server==1&&r.Score[0]==0&&r.Winner<0,"rematch reversed opening");r.Tick(2);r.Pause();check(!r.Live,"pause live");r.Resume();check(r.Live,"resume live");check(!HockeyRules.Crossing(new Vector3(14,0,0),new Vector3(11,0,0),1,12,2.1f,.43f,out _),"backward crossing rejected");check(!HockeyRules.Crossing(new Vector3(14,0,0),new Vector3(15,0,0),1,12,2.1f,.43f,out _),"already beyond rejected");Debug.Log("AH_RULE_FIXTURES_PASS count="+count);}
}
}
